    uint64_t open_refs = 0;
    uint64_t close_in_flight = 0;
  };

  const SystemLoaderOps* ops_;
  std::mutex mutex_;
  std::unordered_map<void*, HandleSlot> handles_;
};

SystemLoader& GlobalSystemLoader();

